def build_notebook():
    notebook = json.loads(_EMBEDDED_NOTEBOOK_JSON)

    for cell in notebook.get("cells", []):
        source = cell.get("source", "")
        if isinstance(source, list):
            cell["source"] = "".join(source)

    return nbformat.from_dict(notebook)


def find_project_root() -> Path:
    for candidate in [Path.cwd(), *Path.cwd().parents]:
        if (
            (candidate / "pyproject.toml").exists()
            and (candidate / "src" / "paper1_qc").exists()
        ):
            return candidate

    raise FileNotFoundError(
        "Run this generator from inside the paper_1 repository."
    )


def main() -> None:
    root = find_project_root()
    output = (
        root
        / "notebooks"
        / "02_feature_extraction"
        / "02e_nonlinear_distortion_QDIST_v3_1_1.ipynb"
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    nbformat.write(build_notebook(), output)
    print(f"Generated: {output}")


if __name__ == "__main__":
    main()
